 THEN RAISE;END IF;END;IF EXISTS(SELECT 1 FROM pipeline_control.admin_record_audit WHERE operation_id=o) OR (SELECT state FROM pipeline_control.admin_record_operations WHERE id=o)<>'preview' THEN RAISE EXCEPTION 'RECORD_ACTION_FIX_PARTIAL_COMMIT';END IF;END $test$;ROLLBACK;